+
 	ret = cci_enable_clocks(cci);
 	if (ret)
 		return ret;
@@ -694,6 +756,19 @@ static int cci_probe(struct platform_device *pdev)
 		return dev_err_probe(dev, PTR_ERR(cci->cci_clk),
 				     "failed to get CCI clock\n");
 
